            package_data=[{"id":o["id"],"name":o["package_name"],"description":o["description"],"price":o["price"],"min":o["min_participants"],"max":o["max_participants"],"duration":o["duration"],"terms":o["terms"]} for o in offers]
            packages_json=json.dumps(package_data,ensure_ascii=False).replace("</","<\\/"); customer_options="".join(f"<option value='{c['id']}'>{esc(c['company'] or c['name'])}{' — '+esc(c['name']) if c['company'] and c['name'] and c['name'] != c['company'] else ''}</option>" for c in contacts); package_options="".join(f"<option value='{o['id']}'>{esc(o['package_name'])}</option>" for o in offers); product_options="".join(f"<option value='{p['id']}'>{esc(p['name'])}</option>" for p in products)
            catalog="".join(f"<tr><td>{esc(o['package_name'])}</td><td>{esc(o['price'])}</td><td>{esc(o['terms'])}</td></tr>" for o in offers) or "<tr><td colspan='3'>Inga paket ännu.</td></tr>"
