def main():
    parser=argparse.ArgumentParser(); parser.add_argument("--host",default="127.0.0.1"); parser.add_argument("--port",type=int,default=8787); parser.add_argument("--db",default="calling_crm.sqlite3"); parser.add_argument("--access-token",default=os.environ.get("CALLING_CRM_ACCESS_TOKEN")); parser.add_argument("--diagnostics",action="store_true"); parser.add_argument("--no-browser",action="store_true"); args=parser.parse_args()
    if args.diagnostics: print(json.dumps(AdbBridge().diagnostics(),ensure_ascii=False,indent=2)); return
    Handler.access_token=args.access_token; Handler.db=Database(args.db); server=ThreadingHTTPServer((args.host,args.port),Handler); url=f"http://{args.host}:{args.port}"; print(f"Calling Platform kör på {url}")
    if not args.no_browser: threading.Timer(.5,lambda:webbrowser.open(url)).start()
    try: server.serve_forever()
    except KeyboardInterrupt: pass
    finally: server.server_close(); Handler.db.close()
